const D = { density:.55, scale:1, glow:.55, energy:.6, speed:1, points:10, hue:45, x:.5, y:.5, style:'illuminated', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const st = P.style;
const n = Math.max(6, Math.min(12, Math.round(P.points)));
const R = u*0.12*(0.55 + P.scale*0.55);
const spacing = Math.max(u*0.105, R*1.7*(1.3 - P.density*0.72));

// ---- compositing buffer (so alpha<100 is true translucency over layers behind) ----
if (!S.fb || S.fbW!==width || S.fbH!==height){ if(S.fb)S.fb.remove(); S.fb=createGraphics(width,height); S.fb.colorMode(HSB,360,100,100,100); S.fbW=width; S.fbH=height; }
const G = S.fb;

// ---- background buffer (jewel ground), keyed on style+hue+size ----
function paintBg(buf, st, hue){
  buf.push(); buf.noStroke();
  let base;
  if (st==='ink') base=[40,12,90];
  else if (st==='stone-relief') base=[34,7,44];
  else if (st==='neon') base=[255,60,5];
  else if (st==='stained-glass') base=[250,42,6];
  else base=[228,66,15];           // illuminated lapis
  buf.background(base[0],base[1],base[2]);
  const cx=buf.width*0.5, cy=buf.height*0.46;
  const g=buf.drawingContext.createRadialGradient(cx,cy,buf.width*0.05, cx,cy,buf.width*0.78);
  if (st==='ink'){ g.addColorStop(0,'rgba(255,252,240,0.10)'); g.addColorStop(1,'rgba(90,60,20,0.22)'); }
  else if (st==='stone-relief'){ g.addColorStop(0,'rgba(255,246,225,0.14)'); g.addColorStop(1,'rgba(0,0,0,0.40)'); }
  else if (st==='illuminated'){ g.addColorStop(0,'rgba(120,150,255,0.18)'); g.addColorStop(0.5,'rgba(40,50,140,0.05)'); g.addColorStop(1,'rgba(0,0,0,0.5)'); }
  else { g.addColorStop(0,'rgba(255,255,255,0.06)'); g.addColorStop(1,'rgba(0,0,0,0.5)'); }
  buf.drawingContext.fillStyle=g; buf.drawingContext.fillRect(0,0,buf.width,buf.height);
  buf.pop();
}
const bgKey=[width,height,st,Math.round(P.hue)].join('|');
if (!S.bg || S.bgKey!==bgKey){ S.bgKey=bgKey; if(S.bg)S.bg.remove(); S.bg=createGraphics(width,height); S.bg.colorMode(HSB,360,100,100,100); paintBg(S.bg,st,P.hue); }

// ---- girih lattice geometry, cached in centered coords ----
const geoKey=[width,height,n,R.toFixed(1),spacing.toFixed(1),P.seed,P.x.toFixed(2),P.y.toFixed(2)].join('|');
if (S.geoKey!==geoKey){
  S.geoKey=geoKey;
  let z=((P.seed*2246822519)>>>0)^0x9e3779b9; z=(z+2654435761)>>>0;
  const rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  const cxC=width*0.5, cyC=height*0.5;
  const cx0=cxC + (P.x-0.5)*spacing, cy0=cyC + (P.y-0.5)*spacing;
  const pad=0.5*Math.hypot(width,height)+spacing;   // build past frame so rotation shows no gap
  const rng=Math.ceil(pad/spacing)+1;
  const skip=Math.max(2, Math.round(n/3));
  const rin=R*0.42;
  let ros=[];
  for (let gy=-rng; gy<=rng; gy++) for (let gx=-rng; gx<=rng; gx++){
    const cx=gx*spacing + ((gy&1)?spacing*0.5:0) + cx0;
    const cy=gy*spacing*0.9 + cy0;
    const d=Math.hypot(cx-cxC, cy-cyC);
    if (d>pad) continue;
    const phi=(rnd()*0.5) + (((gx+gy)&1)?Math.PI/n:0);
    ros.push({cx:cx, cy:cy, phi:phi, d:d});
  }
  ros.sort((a,b)=>a.d-b.d);
  const CAP=58; if (ros.length>CAP) ros=ros.slice(0,CAP);
  const segs=[], polys=[];
  const cxC2=width*0.5, cyC2=height*0.5;
  for (let ri=0; ri<ros.length; ri++){
    const o=ros[ri];
    const outer=[], valley=[];
    for (let k=0;k<n;k++){ const a=o.phi+k*(2*Math.PI/n); outer.push([o.cx+Math.cos(a)*R-cxC2, o.cy+Math.sin(a)*R-cyC2]); }
    for (let k=0;k<n;k++){ const a=o.phi+(k+0.5)*(2*Math.PI/n); valley.push([o.cx+Math.cos(a)*rin-cxC2, o.cy+Math.sin(a)*rin-cyC2]); }
    const poly=[]; for (let k=0;k<n;k++){ poly.push(outer[k]); poly.push(valley[k]); }
    polys.push(poly);
    for (let k=0;k<n;k++){ const b=outer[(k+skip)%n]; segs.push([outer[k][0],outer[k][1],b[0],b[1]]); }        // star interlace chords
    for (let k=0;k<n;k++){ const a=outer[k], b=valley[k]; segs.push([a[0],a[1],b[0],b[1]]); }                   // petal legs
    for (let k=0;k<n;k++){ const a=o.phi+k*(2*Math.PI/n); const ex=o.cx+Math.cos(a)*(spacing*0.52)-cxC2, ey=o.cy+Math.sin(a)*(spacing*0.52)-cyC2; segs.push([outer[k][0],outer[k][1],ex,ey]); }  // neighbour connectors
  }
  for (let i=0;i<segs.length;i++){ const s=segs[i]; s.push((s[0]+s[2])*0.5, (s[1]+s[3])*0.5); }
  S.segs=segs; S.polys=polys;
  S.pal=[]; for (let i=0;i<10;i++) S.pal.push([(P.hue+i*37+rnd()*26)%360, 46+rnd()*38, 44+rnd()*40]);
}

// ==== render whole scene into G ====
G.image(S.bg,0,0);

const segs=S.segs, polys=S.polys, pal=S.pal;
const sec=(K.section!=null?K.section:0), intn=(K.intensity!=null?K.intensity:0.6);
const t=(K.t||0);
// --- MOTION FLOOR: slow global rotation + breath + travelling highlight + hue drift (all incommensurate, never re-phase) ---
const rot=t*0.010*(0.5+P.speed*0.9) + Math.sin(t*0.047)*0.05;
const breath=1 + 0.028*Math.sin(t*0.21) + (K.swell||0)*0.02 + (A.rms||0)*0.03;
const dir=t*0.06 + sec*0.5; const cd=Math.cos(dir), sd2=Math.sin(dir);
const invR=1/(u*0.85);
const bandFreq=2.1 + P.density*1.8;
const bandSpeed=t*(0.32 + P.speed*0.45);
const gpow=4.6 - P.glow*3.4;
const baseHue=(P.hue + sec*6 + Math.sin(t*0.07)*10);
const expo=0.5 + P.energy*0.55 + intn*0.3;
const beat=(K.pulse||0)*0.5 + (A.rms||0)*1.0 + (A.bass||0)*0.6;
const wk=(u/900)*(0.7 + P.scale*0.5);

G.push();
G.translate(width*0.5, height*0.5);
G.rotate(rot);
G.scale(breath);
G.strokeCap(ROUND); G.strokeJoin(ROUND);

// ---- colour-mass tile fills (illuminated subtle / stained-glass bold) ----
if (st==='illuminated' || st==='stained-glass'){
  G.noStroke();
  const fillA = st==='stained-glass' ? 82 : 20;
  const briK  = st==='stained-glass' ? 1.0 : 0.55;
  for (let ri=0; ri<polys.length; ri++){
    const poly=polys[ri], pc=pal[ri%pal.length];
    const w=0.5+0.5*Math.sin((((poly[0][0]*cd+poly[0][1]*sd2)*invR)*bandFreq - bandSpeed)*6.2831);
    G.fill(pc[0], pc[1], Math.min(100, pc[2]*briK*(0.7+0.5*intn) + w*14 + beat*6), fillA);
    G.beginShape(); for (let j=0;j<poly.length;j++) G.vertex(poly[j][0],poly[j][1]); G.endShape(CLOSE);
  }
}

if (st==='neon') G.blendMode(ADD);

// ---- strapwork ribbons with travelling luminous highlight ----
for (let i=0;i<segs.length;i++){
  const s=segs[i], mx=s[4], my=s[5];
  const proj=(mx*cd+my*sd2)*invR;
  const w=0.5+0.5*Math.sin((proj*bandFreq - bandSpeed)*6.2831);
  const g=Math.pow(w, gpow);           // narrow travelling highlight band

  if (st==='illuminated'){
    G.stroke(38, 58, 10, 92); G.strokeWeight(7.2*wk); G.line(s[0],s[1],s[2],s[3]);
    const hh=44 + Math.sin(proj*2.3 + t*0.09)*7;
    const br=Math.min(100, 50 + P.energy*22 + g*40 + beat*10);
    G.stroke(hh, 66 - g*48, br, 97); G.strokeWeight(2.6*wk); G.line(s[0],s[1],s[2],s[3]);
    if (g>0.72){ G.stroke(50, 14, 100, (g-0.72)*300); G.strokeWeight(1.3*wk); G.line(s[0],s[1],s[2],s[3]); }
  } else if (st==='stained-glass'){
    G.stroke(245, 28, 7, 96); G.strokeWeight(6.4*wk); G.line(s[0],s[1],s[2],s[3]);            // dark leading
    G.stroke((baseHue+40)%360, 22, Math.min(100, 60 + g*38 + beat*8), 40 + g*45); G.strokeWeight(1.8*wk); G.line(s[0],s[1],s[2],s[3]);
  } else if (st==='neon'){
    G.stroke((baseHue + g*24)%360, 92 - g*30, 26 + g*24, 30); G.strokeWeight((5.5 + g*4)*wk); G.line(s[0],s[1],s[2],s[3]);  // halo
    G.stroke((baseHue + 12 + g*30)%360, 70 - g*40, Math.min(100, 60 + g*40 + beat*14), 70); G.strokeWeight(1.5*wk); G.line(s[0],s[1],s[2],s[3]); // core
  } else if (st==='stone-relief'){
    const off=1.6*wk;
    G.stroke(30, 10, 8, 60); G.strokeWeight(4.6*wk); G.line(s[0]+off,s[1]+off,s[2]+off,s[3]+off);           // cast shadow
    G.stroke(38, 6, Math.min(100, 62 + g*30), 85); G.strokeWeight(2.8*wk); G.line(s[0]-off*0.6,s[1]-off*0.6,s[2]-off*0.6,s[3]-off*0.6); // lit face
  } else if (st==='ink'){
    const jit=0.55 + 0.5*Math.abs(Math.sin(i*2.3 + t*0.02));
    G.stroke(34, 14, 16, (66 + g*16)*jit); G.strokeWeight((3.4 - g*0.8)*wk*jit); G.line(s[0],s[1],s[2],s[3]);
  }
}

// central beat bloom (partial-frame, additive — never a full flash)
if (beat>0.06 && st!=='ink' && st!=='stone-relief'){
  G.noStroke(); G.blendMode(ADD);
  const bh = st==='neon'? baseHue%360 : (st==='stained-glass'?(baseHue+30)%360:46);
  for (let ri=0; ri<polys.length; ri+=2){
    const poly=polys[ri]; let cx=0,cy=0; for (let j=0;j<poly.length;j++){cx+=poly[j][0];cy+=poly[j][1];}
    cx/=poly.length; cy/=poly.length;
    G.fill(bh, 40, 100, Math.min(22, beat*13)); G.circle(cx, cy, R*0.55*breath);
  }
}
G.blendMode(BLEND);
G.pop();

// ---- blit to main canvas; tint alpha gives true translucency for VJ compositing ----
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(G,0,0,width,height);
pop();
